class TicTacToe:
    EMPTY_CELL = ' '
    PLAYER_X = 'X'
    PLAYER_O = 'O'
    BOARD_SIZE = 3

    def __init__(self, N=3):
        self.board = [[self.EMPTY_CELL for _ in range(self.BOARD_SIZE)] for _ in range(self.BOARD_SIZE)]
        self.current_player = self.PLAYER_X
        self._N = N

    def make_move(self, row, col):
        if self._is_cell_empty(row, col):
            self.board[row][col] = self.current_player
            self._switch_player()
            return True
        return False

    def _is_cell_empty(self, row, col):
        return self.board[row][col] == self.EMPTY_CELL

    def _switch_player(self):
        self.current_player = self.PLAYER_O if self.current_player == self.PLAYER_X else self.PLAYER_X

    def check_winner(self):
        winner = self._check_rows()
        if winner is not None:
            return winner
        winner = self._check_columns()
        if winner is not None:
            return winner
        winner = self._check_diagonals()
        if winner is not None:
            return winner
        return None

    def _check_rows(self):
        for row in self.board:
            if self._is_row_uniform(row):
                return row[0]
        return None

    def _check_columns(self):
        for col in range(self.BOARD_SIZE):
            if self._is_column_uniform(col):
                return self.board[0][col]
        return None

    def _check_diagonals(self):
        if self._is_main_diagonal_uniform():
            return self.board[0][0]
        if self._is_anti_diagonal_uniform():
            return self.board[0][self.BOARD_SIZE - 1]
        return None

    def _is_row_uniform(self, row):
        return row[0] == row[1] == row[2] != self.EMPTY_CELL

    def _is_column_uniform(self, col):
        return (self.board[0][col] == self.board[1][col] == self.board[2][col] != self.EMPTY_CELL)

    def _is_main_diagonal_uniform(self):
        return (self.board[0][0] == self.board[1][1] == self.board[2][2] != self.EMPTY_CELL)

    def _is_anti_diagonal_uniform(self):
        return (self.board[0][self.BOARD_SIZE - 1] == self.board[1][1] == self.board[2][0] != self.EMPTY_CELL)

    def is_board_full(self):
        return not self._has_empty_cells()

    def _has_empty_cells(self):
        for row in self.board:
            if self.EMPTY_CELL in row:
                return True
        return False
